<?php $name=$user['display_name']??'همراه مرشد';$initial=preg_match('/^./us',$name,$first)?$first[0]:''; ?>
<div class="account-hub"><header class="account-welcome"><div class="account-avatar" aria-hidden="true"><?= $this->h($initial) ?></div><div class="account-welcome-text"><span>حساب کاربری مرشد</span><h1><?= $this->h($name) ?><?php if($isMentor??false): ?> <span class="mentor-role-badge">مرشد</span><?php endif; ?></h1><p><bdi>@<?= $this->h($username??'') ?></bdi></p></div><a class="account-edit" href="<?= $this->h($this->url('/account/profile')) ?>"><?= $this->icon('user') ?><span>ویرایش مشخصات</span></a><div class="account-welcome-status"><?= $this->icon('security') ?><?= $user['phone']?'شماره همراه تأیید شده':'شماره همراه ثبت نشده' ?></div></header>
<section class="account-shortcuts" aria-label="دسترسی‌های اصلی حساب"><a href="<?= $this->h($this->url('/sessions')) ?>"><span class="hub-icon"><?= $this->icon('calendar') ?></span><strong>درخواست‌های من</strong><small><?= $this->h($counts['pending']) ?> در انتظار پذیرش</small></a><a href="<?= $this->h($this->url('/notifications')) ?>"><span class="hub-icon"><?= $this->icon('chat') ?></span><strong>اعلان‌ها</strong><small><?= $counts['unread']?$this->h($counts['unread']).' اعلان نخوانده':'همهٔ اعلان‌ها' ?></small></a><a href="<?= $this->h($this->url('/account/security')) ?>"><span class="hub-icon"><?= $this->icon('security') ?></span><strong>تنظیمات</strong><small>رمز و روش‌های ورود</small></a></section>

<div class="hub-groups"><section class="hub-menu-group"><h2>گفت‌وگوها و پیگیری‌ها</h2><div class="hub-menu-list"><?php foreach([['calendar','جلسات و آرشیو','زمان‌بندی و تاریخچهٔ گفت‌وگوها','/sessions'],['chat','پشتیبانی و شکایت','پیگیری سؤال‌ها و درخواست‌های پشتیبانی','/support']] as [$icon,$label,$hint,$url]): ?><a class="hub-menu-item" href="<?= $this->h($this->url($url)) ?>"><span class="hub-icon"><?= $this->icon($icon) ?></span><span><strong><?= $label ?></strong><small><?= $hint ?></small></span><?= $this->icon('arrow') ?></a><?php endforeach; ?></div></section>
<section class="hub-menu-group"><h2>حساب و حریم خصوصی</h2><div class="hub-menu-list"><?php foreach([['user','اطلاعات شخصی','نام، استان، شهر و جنسیت','/account/profile'],['security','دستگاه‌های فعال','مشاهده و خروج از نشست‌ها','/account/sessions'],['book','قوانین و شرایط','مشاهدهٔ نسخه و وضعیت پذیرش','/account/rules']] as [$icon,$label,$hint,$url]): ?><a class="hub-menu-item" href="<?= $this->h($this->url($url)) ?>"><span class="hub-icon"><?= $this->icon($icon) ?></span><span><strong><?= $label ?></strong><small><?= $hint ?></small></span><?= $this->icon('arrow') ?></a><?php endforeach; ?><?php if(empty($user['phone'])): ?><a class="hub-menu-item" href="<?= $this->h($this->url('/account/phone')) ?>"><span class="hub-icon"><?= $this->icon('security') ?></span><span><strong>شماره همراه</strong><small>تأیید شماره یا پیداکردن حساب قبلی</small></span><?= $this->icon('arrow') ?></a><?php endif; ?></div></section></div>
<div class="account-signout"><?= $this->start('/logout') ?><button type="submit" class="secondary">خروج از حساب کاربری <?= $this->icon('arrow') ?></button></form><span class="small muted">مرشد؛ گفت‌وگو با مرشد</span></div></div>
